import sys; sys.path.append('src'); from pipeline_topic import get_ch_client; client = get_ch_client(); query = '''INSERT INTO summing_subfield_metrics SELECT subfield, publication_year as year, arrayJoin(if(empty(all_country_codes), ['Unknown'], all_country_codes)) as country_code, source_id, topic, count() as doc_count, sum(fwci) as fwci_sum, sum(percentile) as percentile_sum, sum(toUInt64(is_top_10)) as top_10_sum, sum(toUInt64(is_top_1)) as top_1_sum, sum(toUInt64(oa_status = 'gold')) as gold_count, sum(toUInt64(oa_status = 'diamond')) as diamond_count, sum(toUInt64(oa_status = 'green')) as green_count, sum(toUInt64(oa_status = 'hybrid')) as hybrid_count, sum(toUInt64(oa_status = 'bronze')) as bronze_count, sum(toUInt64(oa_status = 'closed')) as closed_count, sum(toUInt64(language = 'en')) as lang_en, sum(toUInt64(language = 'es')) as lang_es, sum(toUInt64(language = 'pt')) as lang_pt FROM works WHERE subfield != '' AND publication_year >= 1900 GROUP BY subfield, year, country_code, source_id, topic'''; client.command(query); print('Success!')
